begin;

insert into public.tipos_actividad (id, nombre, descripcion) values
  ('4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'clasificacion', 'Arrastra elementos a la categoría correcta'),
  ('9022a3dc-77f3-48ca-b493-a63f4aaedcbf', 'comparador', 'Analiza dos textos u opciones lado a lado'),
  ('9320ca3b-9c19-4b49-a720-26551b3ae444', 'corregir_ortografia', 'Reescribe un texto corrigiendo mayúsculas, tildes y letras que se confunden (b/v, s/c/z, g/j, h) — se aceptan hasta 5 errores.'),
  ('1d9694c4-a078-428a-92dc-896febce11bd', 'etiquetado_texto', 'Selecciona un fragmento de texto y le asigna una etiqueta'),
  ('b98b891f-f800-4a81-988a-67b26bf1b2a7', 'evaluar_videos', 'Evalúa dos videos: uno que respeta las cualidades de la exposición oral y otro que no, marcando cuáles identifica en cada uno.'),
  ('d453abcd-d7ab-4355-af1f-70f76c57fb54', 'opcion_justificacion', 'Elige una opción y justifica en 1-2 líneas'),
  ('9f444642-c253-4872-9764-b58cd1cb274c', 'ordenar_fragmentos', 'Selecciona y ordena fragmentos para armar un texto coherente'),
  ('b2cd1704-0875-44ad-a9bc-890f988c7d82', 'redaccion_checklist', 'Redacta con un límite y autorrevisa con checklist')
on conflict (id) do update set
  nombre = excluded.nombre,
  descripcion = excluded.descripcion;

insert into public.unidades (id, nombre, orden, descripcion, reto_comunicativo, unidad_competencia) values
  ('055b3852-d57b-419c-b08d-6cd21d4c3e5d', 'De la lengua al texto', 1, 'Comunicación, lenguaje, lengua, habla, norma, niveles y funciones de la lengua, el texto y sus propiedades.', 'Sintetizar la idea central de un texto extenso en cinco líneas.', 'Expresa ideas de manera clara y coherente en diversas situaciones comunicativas, respetando las formas básicas de la lengua española y utilizando los recursos lingüísticos adecuados al contexto y propósito del mensaje.'),
  ('f018d57c-10e0-43ed-9112-d003596e02d9', 'Exposición escrita', 2, 'Ortografía y puntuación: uso del punto, la coma, letras que se confunden, acentuación y signos — además de repasar los modelos expositivos ya vistos.', 'Escribir con ortografía y puntuación correctas para comunicar con claridad.', 'Realiza textos de divulgación que se apeguen a las reglas gramaticales, léxicas y sintácticas, para comunicar información con coherencia y cohesión en distintos ámbitos.'),
  ('9f8dc167-716f-40f6-ade9-815849af66f8', 'Exposición oral', 3, 'Cualidades y técnicas de la exposición oral.', 'Exponer ante el grupo con seguridad.', 'Demuestra oralmente mensajes expositivos utilizando las cualidades de la expresión oral para transmitir información de manera eficaz, respetuosa y crítica en contextos académicos y sociales.')
on conflict (id) do update set
  nombre = excluded.nombre,
  orden = excluded.orden,
  descripcion = excluded.descripcion,
  reto_comunicativo = excluded.reto_comunicativo,
  unidad_competencia = excluded.unidad_competencia;

-- Los prerrequisitos se asignan después del upsert para admitir referencias
-- entre actividades del mismo catálogo sin depender del orden de inserción.
insert into public.actividades (
  id, unidad_id, tipo_id, titulo, instrucciones, contenido, orden,
  aprendizaje_esperado, video_url, requiere_actividad_id
) values
  ('ff4539b3-92e5-4f63-9e58-21d01965a300', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'El circuito de la comunicación', 'Sigue paso a paso esta conversación real y ve identificando cada elemento del circuito de la comunicación conforme aparece.', '{"rondas":[{"contexto":"Ana toma su celular y escribe el primer mensaje.","opciones":["Emisor","Receptor","Código","Canal"],"pregunta":"¿Qué elemento del circuito de la comunicación es Ana en este momento?","ideas_clave":["emite","envía","origina"],"mensajesVisibles":1,"respuesta_correcta":"Emisor"},{"contexto":"El mensaje de Ana decía exactamente: \"¿seguimos con lo de mañana?\"","opciones":["El mensaje","El código","El canal","La retroalimentación"],"pregunta":"Ese texto que Ana escribió y envió es:","ideas_clave":["mensaje","contenido","información"],"mensajesVisibles":1,"respuesta_correcta":"El mensaje"},{"contexto":"Ana usó una frase corta e informal, dando por hecho que Luis sabría a qué se refería con \"lo de mañana\".","opciones":["El código","El canal","El receptor","La retroalimentación"],"pregunta":"El lenguaje que Ana eligió para su mensaje (informal, ambiguo, sin contexto explícito) corresponde a:","ideas_clave":["lenguaje","código","ambiguo"],"mensajesVisibles":1,"respuesta_correcta":"El código"},{"contexto":"El mensaje viajó de un celular a otro a través de WhatsApp.","opciones":["El canal","El código","El contexto","El emisor"],"pregunta":"WhatsApp, como medio por el que viajó el mensaje, es:","ideas_clave":["medio","viaja","tecnológico"],"mensajesVisibles":1,"respuesta_correcta":"El canal"},{"contexto":"Luis no tenía ningún plan pendiente con Ana en mente (ambos vivían la conversación con información distinta).","opciones":["El contexto compartido","El canal","El emisor","La retroalimentación"],"pregunta":"Luis no entendió el mensaje porque le faltaba algo del circuito de la comunicación. ¿Qué elemento falló aquí?","ideas_clave":["contexto","compartido","situación"],"mensajesVisibles":1,"respuesta_correcta":"El contexto compartido"},{"contexto":"Al final, Luis fue quien recibió e interpretó el mensaje de Ana (aunque de forma distinta a la que ella esperaba).","opciones":["Receptor","Emisor","Código","Canal"],"pregunta":"En esta conversación, ¿qué papel tuvo Luis como parte del circuito de la comunicación?","ideas_clave":["recibe","interpreta","destinatario"],"mensajesVisibles":1,"respuesta_correcta":"Receptor"},{"contexto":"Tres horas después, Luis responde: \"¿Con lo de qué? No entendí tu mensaje.\"","opciones":["La retroalimentación","El código","El canal","El mensaje original"],"pregunta":"La respuesta de Luis, que le permite a Ana darse cuenta de que su mensaje no se entendió, es:","ideas_clave":["retroalimentación","respuesta","permite"],"mensajesVisibles":2,"respuesta_correcta":"La retroalimentación"},{"contexto":"En su segundo mensaje, Ana ya no dice \"lo de mañana\", sino \"el trabajo de historia, en la biblioteca a las 4\": un lenguaje mucho más claro y específico que el primero.","opciones":["El código","El canal","El emisor","El receptor"],"pregunta":"Esta mejora en la claridad del mensaje corresponde a un ajuste en:","ideas_clave":["claro","específico","lenguaje"],"mensajesVisibles":3,"respuesta_correcta":"El código"},{"contexto":"Luis responde: \"Ah, ya me acordé. Ahí nos vemos.\" Esta vez sin ninguna confusión.","opciones":["Que el circuito se completó con éxito (el mensaje se entendió)","Que Luis ahora es el emisor","Que ya no hace falta un canal","Que el mensaje original era innecesario"],"pregunta":"¿Qué demuestra la respuesta final de Luis sobre el circuito de la comunicación?","ideas_clave":["completó","entendió","éxito"],"mensajesVisibles":4,"respuesta_correcta":"Que el circuito se completó con éxito (el mensaje se entendió)"}],"mensajes":[{"de":"Ana","texto":"¿Seguimos con lo de mañana?"},{"de":"Luis","nota":"3 horas después","texto":"¿Con lo de qué? No entendí tu mensaje."},{"de":"Ana","nota":"unos minutos después","texto":"El trabajo de historia, quedamos de vernos en la biblioteca a las 4."},{"de":"Luis","texto":"Ah, ya me acordé. Ahí nos vemos."}],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Sigue paso a paso esta conversación real y ve identificando cada elemento del circuito de la comunicación conforme aparece.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 1, 'Identifica los elementos del proceso comunicativo, sus barreras y las tipologías del lenguaje para construir mensajes claros y adaptados al entorno, considerando la importancia de la evolución comunicativa.', 'https://youtu.be/Phdf4GWS-TM', null),
  ('18caf5eb-fb05-4e9e-9268-dcce3f92cb8b', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Contextos normativos de la lengua', 'Clasifica cada expresión según el contexto que la hace "normal": académico, social, cultural o geográfico. ("Normal" aquí significa pertinente al contexto comunicativo, no "correcto" en el sentido común.)', '{"elementos":[{"texto":"\"Dijiste\", \"cafés\", \"¡Ven!\"","categoria_correcta":"Académico"},{"texto":"\"¡Ven pa''cá!\", \"Compré unos zapatos cafeses\"","categoria_correcta":"Social"},{"texto":"\"Este es el cuerpo de Cristo\", \"Ve con Dios\"","categoria_correcta":"Cultural"},{"texto":"\"Chamba\", \"curro\", \"laburo\" (trabajo)","categoria_correcta":"Geográfico"},{"texto":"\"Papalote\", \"voladores\", \"papagayo\" (cometa)","categoria_correcta":"Geográfico"}],"categorias":["Académico","Social","Cultural","Geográfico"],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Clasifica cada expresión según el contexto que la hace \"normal\": académico, social, cultural o geográfico. (\"Normal\" aquí significa pertinente al contexto comunicativo, no \"correcto\" en el sentido común.)","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 2, 'Emplea las funciones de la lengua, los niveles del habla, respetando las normas lingüísticas y adaptando su discurso para evitar deformaciones y responder de manera eficaz a las variaciones del contexto comunicativo.', 'https://youtu.be/8tJKteVc71I', null),
  ('c1696cc5-128e-41b0-abac-999fecef94f4', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Registros lingüísticos', 'Clasifica cada frase según el registro lingüístico que predomina: culto formal, culto informal, inculto formal o inculto informal. No juzgues a la persona: identifica únicamente la forma en que está construido el mensaje.', '{"contexto":"En esta actividad se usa la clasificación detallada de la fuente. El registro depende de la formalidad y del dominio de la norma; identifica el mensaje, no califiques a quien lo dice.","elementos":[{"texto":"La tilde o acento gráfico es un signo que marca la sílaba tónica de una palabra según las reglas de acentuación.","categoria_correcta":"Culto formal"},{"texto":"Conviene revisar las reglas de acentuación antes de redactar un texto formal, pues los errores ortográficos afectan la credibilidad del autor.","categoria_correcta":"Culto formal"},{"texto":"Algunas palabras llevan acento escrito y otras no; las reglas permiten saber cuáles son.","categoria_correcta":"Culto informal"},{"texto":"Yo creo que ahí se pone el acento, pero no estoy muy seguro; así me suena bien.","categoria_correcta":"Culto informal"},{"texto":"No profe, yo no quero revisar la acentuación; solo sé que algunas palabras llevan un palito.","categoria_correcta":"Inculto informal"},{"texto":"No sé, carnal; a mí me suenan igual con o sin rayita, ¿pa'' qué tanto rollo?","categoria_correcta":"Inculto informal"}],"categorias":["Culto formal","Culto informal","Inculto formal","Inculto informal"],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Clasifica cada frase según el registro lingüístico que predomina: culto formal, culto informal, inculto formal o inculto informal. No juzgues a la persona: identifica únicamente la forma en que está construido el mensaje.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 3, 'Emplea las funciones de la lengua, los niveles del habla, respetando las normas lingüísticas y adaptando su discurso para evitar deformaciones y responder de manera eficaz a las variaciones del contexto comunicativo.', 'https://youtu.be/mjQ8s9GPtD4', null),
  ('2a20c2a9-89e0-4d0c-a464-66284af769d2', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Niveles de la lengua', 'Lee el mensaje y elige qué nivel de la lengua emplea.', '{"rondas":[{"opciones":["Coloquial","Técnico-científico","Literario"],"pregunta":"\"La fuerza de empuje es la resultante de las presiones que un fluido ejerce sobre un cuerpo sumergido en él.\" ¿Qué nivel de la lengua usa este mensaje?","ideas_clave":["terminología","especializado","formal"],"respuesta_correcta":"Técnico-científico"},{"opciones":["Coloquial","Técnico-científico","Literario"],"pregunta":"\"Oye, ¿ya viste que se le poncharon las llantas a la combi? Nel, mejor nos vamos caminando.\" ¿Qué nivel de la lengua usa este mensaje?","ideas_clave":["cotidiano","informal","coloquial"],"respuesta_correcta":"Coloquial"},{"opciones":["Coloquial","Técnico-científico","Literario"],"pregunta":"\"El silencio se derramaba entre las calles como una sombra que nadie se atrevía a nombrar.\" ¿Qué nivel de la lengua usa este mensaje?","ideas_clave":["figurado","metáfora","estético"],"respuesta_correcta":"Literario"}],"presentacion":"todas_juntas","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee el mensaje y elige qué nivel de la lengua emplea.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 4, 'Emplea las funciones de la lengua, los niveles del habla, respetando las normas lingüísticas y adaptando su discurso para evitar deformaciones y responder de manera eficaz a las variaciones del contexto comunicativo.', 'https://youtu.be/6r_iqjGjpQw', null),
  ('5edf9aa1-88c9-4e22-9c97-781a684c5574', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Tipologías textuales', 'Lee cada fragmento y elige qué tipología textual lo caracteriza.', '{"rondas":[{"opciones":["Narración","Descripción","Argumentación","Exposición","Diálogo"],"pregunta":"La autorregulación del aprendizaje debería enseñarse desde la educación básica, porque un estudiante que aprende a planear, monitorear y evaluar su propio proceso no depende de que alguien más le diga qué hacer. Además, quien se autorregula aprovecha mejor su tiempo y enfrenta con más confianza los retos académicos que vienen después.","ideas_clave":["postura","razones","defiende"],"respuesta_correcta":"Argumentación"},{"opciones":["Narración","Descripción","Argumentación","Exposición","Diálogo"],"pregunta":"Cuando Marisol se dio cuenta de que reprobaría el examen si seguía solo memorizando, decidió cambiar de estrategia: empezó a hacerse preguntas antes de leer, después subrayaba lo que no entendía y al final de cada semana repasaba sus propios apuntes en voz alta. Tres semanas después, su calificación había subido diez puntos.","ideas_clave":["secuencia","tiempo","hechos"],"respuesta_correcta":"Narración"},{"opciones":["Narración","Descripción","Argumentación","Exposición","Diálogo"],"pregunta":"El agua es uno de los elementos más importantes de la Tierra: cubre las tres cuartas partes de nuestro planeta y, sin agua, ningún ser vivo podría vivir.","ideas_clave":["información","datos","objetivo"],"respuesta_correcta":"Exposición"},{"opciones":["Narración","Descripción","Argumentación","Exposición","Diálogo"],"pregunta":"Un espacio de aprendizaje autónomo bien diseñado tiene pocas distracciones, buena luz natural, un reloj visible y materiales de consulta ordenados por tema. El estudiante autorregulado suele tener a la mano una libreta de metas semanales y un calendario donde marca su avance.","ideas_clave":["características","cualidades","enumera"],"respuesta_correcta":"Descripción"}],"presentacion":"todas_juntas","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee cada fragmento y elige qué tipología textual lo caracteriza.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 5, 'Distingue las tipologías de párrafos por su estructura y función, examinando la articulación entre ideas principales y secundarias para seleccionar las técnicas de procesamiento más adecuadas para su análisis.', 'https://youtu.be/ZQTgPPo03vA', null),
  ('647b744e-c24a-42c2-b6af-6b0e22205df7', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '1d9694c4-a078-428a-92dc-896febce11bd', 'Variaciones y deformaciones de la lengua', 'Etiqueta cada expresión: Caló o Jerga si muestra una forma de hablar propia de un grupo social o profesional; Regionalismo si cambia según la región; Modismo si es un dicho o expresión con sentido figurado.', '{"contexto":"Las deformaciones son transformaciones del código usadas por grupos sociales o profesionales: caló y jerga. Las variaciones dependen de la región o del sentido cultural de la expresión: regionalismos y modismos. Clasifica por el rasgo que explica cada ejemplo.","etiquetas":["Caló","Jerga","Regionalismo","Modismo"],"fragmentos":[{"texto":"Ya chole, chango chilango; qué chafa chamba te chutas.","etiqueta_correcta":"Caló"},{"texto":"En plan, no tengo tema con mi besti; estuvo random.","etiqueta_correcta":"Caló"},{"texto":"En el partido, el árbitro marcó fuera de lugar y el delantero quedó en posición adelantada.","etiqueta_correcta":"Jerga"},{"texto":"La brigada revisó el cárter, cambió la bujía y ajustó el torque del motor.","etiqueta_correcta":"Jerga"},{"texto":"Para referirse al transporte público, en México dicen «camión» y en el Caribe «guagua».","etiqueta_correcta":"Regionalismo"},{"texto":"Al mismo objeto se le llama «popote», «pitillo» o «pajilla» según la región.","etiqueta_correcta":"Regionalismo"},{"texto":"El que es perico, dondequiera es verde.","etiqueta_correcta":"Modismo"},{"texto":"Aquí hay gato encerrado.","etiqueta_correcta":"Modismo"}],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Etiqueta cada expresión: Caló o Jerga si muestra una forma de hablar propia de un grupo social o profesional; Regionalismo si cambia según la región; Modismo si es un dicho o expresión con sentido figurado.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 6, 'Emplea las funciones de la lengua, los niveles del habla, respetando las normas lingüísticas y adaptando su discurso para evitar deformaciones y responder de manera eficaz a las variaciones del contexto comunicativo.', 'https://youtu.be/B2JWzheCeMM', null),
  ('c9f51506-62fb-47b5-aeed-1a18d3820f40', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Las 6 funciones de la lengua', 'Clasifica cada mensaje según la función de la lengua que lo caracteriza.', '{"elementos":[{"texto":"\"Mañana no hay clases.\"","categoria_correcta":"Referencial"},{"texto":"\"¡Me siento genial!\"","categoria_correcta":"Expresiva"},{"texto":"\"¿Te gustaría ir al cine conmigo?\"","categoria_correcta":"Apelativa"},{"texto":"\"¡Buenos días!\"","categoria_correcta":"Fática"},{"texto":"\"El que es perico dondequiera es verde.\"","categoria_correcta":"Poética"},{"texto":"\"Las palabras esdrújulas siempre se tildan.\"","categoria_correcta":"Metalingüística"},{"texto":"\"El agua hierve a 100 grados centígrados al nivel del mar.\"","categoria_correcta":"Referencial"},{"texto":"\"¡Qué alivio, por fin terminé la tarea!\"","categoria_correcta":"Expresiva"},{"texto":"\"Guarda silencio, por favor.\"","categoria_correcta":"Apelativa"},{"texto":"\"¿Bueno? ¿Me escuchas?\"","categoria_correcta":"Fática"},{"texto":"\"Verde que te quiero verde.\"","categoria_correcta":"Poética"},{"texto":"\"Águila\" es una palabra esdrújula.","categoria_correcta":"Metalingüística"}],"categorias":["Referencial","Expresiva","Apelativa","Fática","Poética","Metalingüística"],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Clasifica cada mensaje según la función de la lengua que lo caracteriza.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 7, 'Emplea las funciones de la lengua, los niveles del habla, respetando las normas lingüísticas y adaptando su discurso para evitar deformaciones y responder de manera eficaz a las variaciones del contexto comunicativo.', 'https://youtu.be/XUGMrJ_Ts1c', null),
  ('7bafc22d-9b82-4b16-892c-bb9244e42177', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Las 6 funciones de la lengua (nivel 2)', 'Clasifica cada mensaje, más largo y menos evidente que en el nivel anterior, según la función de la lengua que lo caracteriza.', '{"elementos":[{"texto":"Según la Encuesta Nacional de Consumo de Contenidos Audiovisuales 2023 del IFT, el teléfono celular fue el dispositivo más utilizado por niñas, niños y adolescentes para consumir contenidos por internet: 78%.","categoria_correcta":"Referencial"},{"texto":"No puedo creer que después de tantos meses de esfuerzo, cuando por fin sentía que lo tenía controlado, todo se haya derrumbado en un solo día; de verdad no sé cómo seguir.","categoria_correcta":"Expresiva"},{"texto":"Antes de que sea demasiado tarde, te pido que lo pienses con calma: habla con ella, discúlpate si hace falta, y no dejes que el orgullo decida por ti.","categoria_correcta":"Apelativa"},{"texto":"Oye, ¿sigues ahí? Es que hace rato que no dices nada y ya me preocupé, ¿todo bien de tu lado?","categoria_correcta":"Fática"},{"texto":"El río se despide del monte con un murmullo de piedras, y la tarde, cansada de tanto sol, se recuesta despacio sobre el pueblo.","categoria_correcta":"Poética"},{"texto":"Cuando decimos que una palabra es \"aguda\", nos referimos a que su sílaba tónica (la que suena con más fuerza) cae en la última posición, como ocurre en \"camión\" o \"reloj\".","categoria_correcta":"Metalingüística"}],"categorias":["Referencial","Expresiva","Apelativa","Fática","Poética","Metalingüística"],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Clasifica cada mensaje, más largo y menos evidente que en el nivel anterior, según la función de la lengua que lo caracteriza.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 8, 'Emplea las funciones de la lengua, los niveles del habla, respetando las normas lingüísticas y adaptando su discurso para evitar deformaciones y responder de manera eficaz a las variaciones del contexto comunicativo.', 'https://youtu.be/XUGMrJ_Ts1c', null),
  ('0575064a-7e76-4c22-bc6b-fb3a689f7838', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Ideas principales, secundarias y terciarias', 'Lee el párrafo. La primera oración presenta el tema; clasifica las seis oraciones siguientes según su nivel de importancia.', '{"contexto":"Muchos estudiantes creen que estudiar más horas garantiza mejores resultados. La práctica distribuida en varios días fortalece más las conexiones neuronales que una sola sesión maratónica. Repasar un tema 20 minutos cada día durante una semana deja mejores resultados que estudiarlo tres horas seguidas la noche anterior. Dormir bien entre cada sesión de repaso ayuda a consolidar lo aprendido en la memoria de largo plazo. Por otro lado, intercalar distintos temas en una misma sesión de estudio, en vez de agotar uno solo antes de pasar al siguiente, mejora la capacidad de distinguir entre conceptos parecidos. Esto ocurre porque el cerebro se ve obligado a decidir activamente qué estrategia usar para cada tipo de problema, en vez de aplicar la misma de forma automática. Por lo tanto, la forma en que se organiza el tiempo de estudio importa tanto como la cantidad de horas invertidas.","elementos":[{"texto":"La práctica distribuida en varios días fortalece más las conexiones neuronales que una sola sesión maratónica.","categoria_correcta":"Idea secundaria"},{"texto":"Repasar un tema 20 minutos cada día durante una semana deja mejores resultados que estudiarlo tres horas seguidas la noche anterior.","categoria_correcta":"Idea terciaria"},{"texto":"Dormir bien entre cada sesión de repaso ayuda a consolidar lo aprendido en la memoria de largo plazo.","categoria_correcta":"Idea terciaria"},{"texto":"Intercalar distintos temas en una misma sesión de estudio, en vez de agotar uno solo antes de pasar al siguiente, mejora la capacidad de distinguir entre conceptos parecidos.","categoria_correcta":"Idea secundaria"},{"texto":"Esto ocurre porque el cerebro se ve obligado a decidir activamente qué estrategia usar para cada tipo de problema, en vez de aplicar la misma de forma automática.","categoria_correcta":"Idea terciaria"},{"texto":"Por lo tanto, la forma en que se organiza el tiempo de estudio importa tanto como la cantidad de horas invertidas.","categoria_correcta":"Idea principal"}],"categorias":["Idea principal","Idea secundaria","Idea terciaria"],"reintento_alternativo":{"elementos":[{"texto":"Organizar las ideas antes de escribir facilita que el lector siga el mensaje.","categoria_correcta":"Idea principal"},{"texto":"Un esquema permite decidir qué información debe aparecer primero.","categoria_correcta":"Idea secundaria"},{"texto":"También ayuda a detectar repeticiones y datos que no aportan al propósito.","categoria_correcta":"Idea secundaria"},{"texto":"Si una idea explica a otra más general, funciona como apoyo terciario.","categoria_correcta":"Idea terciaria"},{"texto":"Releer el borrador permite ajustar el orden y la relación entre las partes.","categoria_correcta":"Idea secundaria"},{"texto":"La claridad del texto depende de que sus ideas mantengan una relación comprensible.","categoria_correcta":"Idea principal"}],"categorias":["Idea principal","Idea secundaria","Idea terciaria"]},"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee el párrafo. La primera oración presenta el tema; clasifica las seis oraciones siguientes según su nivel de importancia.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 9, 'Distingue las tipologías de párrafos por su estructura y función, examinando la articulación entre ideas principales y secundarias para seleccionar las técnicas de procesamiento más adecuadas para su análisis.', 'https://youtu.be/qkSf4y_gc2g', null),
  ('7607c583-2732-40d4-bc22-a5b057b6a9ce', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Ideas principales, secundarias y terciarias (nivel 2)', 'Lee el párrafo y clasifica cada oración según su nivel de importancia. Esta vez las opciones no son fragmentos literales del texto, sino interpretaciones (piensa en lo que cada una representa dentro del párrafo, no en si aparece igual).', '{"contexto":"Intercambiar textos entre compañeros para corregirse ayuda a detectar errores que el autor no había notado por sí mismo. Explicarle a otra persona por qué una oración no se entiende obliga a poner en palabras un criterio que, de otro modo, permanece intuitivo. Además, recibir comentarios de alguien que no conoce el tema tan a fondo como el profesor revela qué partes del texto dependen de información que el lector no tiene. Por otro lado, la retroalimentación entre pares también reduce la ansiedad de mostrar un primer borrador. Esto ocurre porque, al ver los errores de otros, cada quien entiende que equivocarse en un borrador es esperado, no vergonzoso. Por eso, incorporar la revisión entre compañeros en cualquier proceso de escritura mejora tanto el texto final como la actitud de quien escribe.","elementos":[{"texto":"El intercambio de textos entre compañeros funciona como una segunda mirada que el autor, por estar tan cerca de su propio trabajo, no puede tener.","categoria_correcta":"Idea secundaria"},{"texto":"Poner en palabras por qué algo no se entiende exige volver explícito un criterio de escritura que normalmente se aplica sin pensar.","categoria_correcta":"Idea terciaria"},{"texto":"Un lector que no domina el tema deja ver, sin querer, qué información el texto da por sabida sin explicarla.","categoria_correcta":"Idea terciaria"},{"texto":"Compartir un borrador con otros vuelve el error algo colectivo y esperado, no una falla personal que hay que esconder.","categoria_correcta":"Idea secundaria"},{"texto":"Ver que los demás también se equivocan normaliza el hecho de equivocarse en un primer intento.","categoria_correcta":"Idea terciaria"},{"texto":"El valor de la retroalimentación entre compañeros no está solo en mejorar el texto, sino en cambiar cómo se vive el proceso de escribir.","categoria_correcta":"Idea principal"}],"categorias":["Idea principal","Idea secundaria","Idea terciaria"],"reintento_alternativo":{"elementos":[{"texto":"La práctica deliberada ayuda a convertir una habilidad difícil en un procedimiento más seguro.","categoria_correcta":"Idea principal"},{"texto":"El estudiante revisa sus errores después de cada ejercicio.","categoria_correcta":"Idea secundaria"},{"texto":"Esa revisión le permite elegir una estrategia distinta para el siguiente intento.","categoria_correcta":"Idea terciaria"},{"texto":"La persona registra qué parte de la consigna le costó más trabajo.","categoria_correcta":"Idea secundaria"},{"texto":"Con el tiempo, comparar los resultados fortalece su autonomía.","categoria_correcta":"Idea terciaria"},{"texto":"Por eso, aprender no consiste solamente en repetir una respuesta.","categoria_correcta":"Idea principal"}],"categorias":["Idea principal","Idea secundaria","Idea terciaria"]},"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee el párrafo y clasifica cada oración según su nivel de importancia. Esta vez las opciones no son fragmentos literales del texto, sino interpretaciones (piensa en lo que cada una representa dentro del párrafo, no en si aparece igual).","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 10, 'Distingue las tipologías de párrafos por su estructura y función, examinando la articulación entre ideas principales y secundarias para seleccionar las técnicas de procesamiento más adecuadas para su análisis.', 'https://youtu.be/AmrkfWLJQ38', null),
  ('a0ba1541-2eec-4b11-809b-9cdcc9bae10b', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '9f444642-c253-4872-9764-b58cd1cb274c', 'Coherencia global del texto', 'De los 6 fragmentos, elige los 3 que juntos forman un mensaje coherente sobre interculturalidad y ordénalos para que se lea con sentido. Los otros 3 son del mismo tema, pero no encajan en este argumento (léelos con cuidado).', '{"contexto":"Estos 6 fragmentos incluyen 3 que sí arman un mensaje coherente (en cierto orden) y 3 distractores del mismo tema que no encajan en el argumento. Elige solo los que pertenecen y ordénalos para que se lea con coherencia.","fragmentos":["Muchos países han creado políticas públicas para proteger las lenguas indígenas de sus regiones.","Este diálogo exige reconocer que ninguna cultura posee una perspectiva completa o neutral sobre el mundo.","La globalización ha facilitado que las personas trabajen y estudien en países distintos al suyo con mayor frecuencia.","La interculturalidad no consiste en que las culturas coexistan sin comunicarse, sino en que dialoguen y se enriquezcan mutuamente.","Algunos estudios señalan que dominar más de un idioma mejora la memoria y la capacidad de resolver problemas.","Por ello, las instituciones educativas tienen la responsabilidad de formar estudiantes capaces de cuestionar sus propios supuestos culturales antes de juzgar los ajenos."],"orden_correcto":[3,1,5],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"De los 6 fragmentos, elige los 3 que juntos forman un mensaje coherente sobre interculturalidad y ordénalos para que se lea con sentido. Los otros 3 son del mismo tema, pero no encajan en este argumento (léelos con cuidado).","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 11, 'Distingue las tipologías de párrafos por su estructura y función, examinando la articulación entre ideas principales y secundarias para seleccionar las técnicas de procesamiento más adecuadas para su análisis.', 'https://youtu.be/ATtK2YCV9DE', null),
  ('7b193adc-e056-4c19-89ed-43132381fd4f', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', 'b2cd1704-0875-44ad-a9bc-890f988c7d82', 'El resumen imposible', 'Lee los 3 ejemplos ya resueltos del mismo artículo (resumen, síntesis y paráfrasis) y compáralos: fíjate qué conserva cada uno y qué cambia entre ellos.', '{"modo":"leer_reflexionar","texto_fuente":"Los adolescentes de hoy están inmersos en una era digital que ha transformado la forma en que se comunican, aprenden y se entretienen. Tanto las ventajas como los riesgos están latentes y nuestros jóvenes resultan una población vulnerable. Por una parte, los dispositivos electrónicos, como smartphones y tabletas, se han vuelto compañeros constantes en sus vidas. Aunque la tecnología ofrece numerosas ventajas, como acceso a información y redes sociales, también plantea desafíos, como el tiempo excesivo frente a las pantallas y la privacidad en línea. Es esencial que los adolescentes aprendan a equilibrar el uso de la tecnología con actividades offline para su bienestar. La educación en línea se ha convertido en una parte fundamental de la vida estudiantil de los adolescentes. La pandemia de COVID-19 aceleró este cambio, y muchos jóvenes se han adaptado a la educación a distancia. A pesar de sus ventajas en cuanto a flexibilidad y acceso a recursos educativos, los adolescentes enfrentan desafíos como la falta de interacción social en el entorno escolar tradicional. Por otra parte, a través de plataformas como Instagram, TikTok y Snapchat, pueden conectarse con amigos, compartir sus vidas y expresar su creatividad. Las redes sociales desempeñan un papel importante en la vida de los adolescentes, aunque es importante comprender los riesgos asociados con el acoso cibernético y la gestión de la privacidad en línea.","titulo_fuente":"El impacto de la tecnología en la vida de los adolescentes","ejemplo_resumen":"Los adolescentes viven en una era digital que transformó cómo se comunican, aprenden y se entretienen, con ventajas y riesgos para esta población vulnerable. Los dispositivos electrónicos son compañeros constantes: dan acceso a información y redes sociales, pero también traen tiempo excesivo frente a pantallas y problemas de privacidad, por lo que es esencial equilibrar su uso con actividades offline. La educación en línea, acelerada por la pandemia, ofrece flexibilidad y acceso a recursos, aunque reduce la interacción social presencial. Las redes sociales permiten conectarse, compartir y expresar creatividad, pero conllevan riesgos como el acoso cibernético y el manejo de la privacidad.","ejemplo_sintesis":"La tecnología atraviesa por completo la vida adolescente actual: los conecta, los entretiene y los educa, pero al mismo tiempo los expone a distracción, aislamiento social y riesgos de privacidad (el reto real no es rechazarla ni depender de ella, sino aprender a usarla con equilibrio).","ejemplo_parafrasis":"En la actualidad, quienes están en la adolescencia crecen rodeados de dispositivos digitales que han cambiado por completo su manera de relacionarse, informarse y divertirse; esto trae beneficios, pero también expone a este grupo a ciertos peligros. Los celulares y tabletas los acompañan todo el tiempo: por un lado, les dan acceso rápido a información y a la vida social en línea; por otro, los exponen a pasar demasiadas horas frente a una pantalla y a exponer su información personal, así que resulta necesario que combinen su vida digital con actividades fuera de la pantalla. Estudiar a distancia, algo que se volvió común desde la pandemia, les ofrece comodidad y materiales variados, aunque a cambio conviven menos cara a cara con sus compañeros de escuela. De igual manera, aplicaciones como Instagram, TikTok o Snapchat les permiten mantenerse en contacto con otros, mostrar quiénes son y ser creativos, sin dejar de lado que existen peligros como el acoso en línea y el cuidado de sus datos personales.","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee los 3 ejemplos ya resueltos del mismo artículo (resumen, síntesis y paráfrasis) y compáralos: fíjate qué conserva cada uno y qué cambia entre ellos.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 12, 'Distingue las tipologías de párrafos por su estructura y función, examinando la articulación entre ideas principales y secundarias para seleccionar las técnicas de procesamiento más adecuadas para su análisis.', 'https://youtu.be/KyugQGU_dH0', null),
  ('0b545726-db56-42d6-8d1e-a34118c62cfc', '055b3852-d57b-419c-b08d-6cd21d4c3e5d', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Practica tu resumen', 'Realiza un resumen del texto con las ideas que sí deben incluirse. Después clasifica las oraciones según si van o no van en el resumen.', '{"contexto":"Los emojis se han convertido en una parte habitual de la comunicación escrita cotidiana, especialmente entre los adolescentes. Surgieron en Japón en 1999, creados por Shigetaka Kurita para un servicio de mensajería móvil. A diferencia de las palabras, los emojis pueden expresar tono y emoción de forma inmediata, sin necesidad de una oración completa. Por ejemplo, un mismo mensaje de texto puede sonar serio o en broma dependiendo del emoji que lo acompañe. Sin embargo, su significado no siempre es universal: un mismo emoji puede interpretarse de manera distinta según la edad, la cultura o incluso el dispositivo desde el que se envía. Algunos estudios muestran que ciertas empresas ya usan emojis en su comunicación interna para agilizar mensajes cortos. En conjunto, los emojis funcionan como un lenguaje complementario que aporta matices emocionales difíciles de lograr solo con texto, aunque su ambigüedad puede generar malentendidos si no se usan con cuidado.","elementos":[{"texto":"Los emojis se han convertido en una parte habitual de la comunicación escrita cotidiana, especialmente entre los adolescentes.","categoria_correcta":"Va en el resumen"},{"texto":"Surgieron en Japón en 1999, creados por Shigetaka Kurita para un servicio de mensajería móvil.","categoria_correcta":"No va en el resumen"},{"texto":"A diferencia de las palabras, los emojis pueden expresar tono y emoción de forma inmediata, sin necesidad de una oración completa.","categoria_correcta":"Va en el resumen"},{"texto":"Por ejemplo, un mismo mensaje de texto puede sonar serio o en broma dependiendo del emoji que lo acompañe.","categoria_correcta":"No va en el resumen"},{"texto":"Sin embargo, su significado no siempre es universal: un mismo emoji puede interpretarse de manera distinta según la edad, la cultura o incluso el dispositivo desde el que se envía.","categoria_correcta":"Va en el resumen"},{"texto":"Algunos estudios muestran que ciertas empresas ya usan emojis en su comunicación interna para agilizar mensajes cortos.","categoria_correcta":"No va en el resumen"},{"texto":"En conjunto, los emojis funcionan como un lenguaje complementario que aporta matices emocionales difíciles de lograr solo con texto, aunque su ambigüedad puede generar malentendidos si no se usan con cuidado.","categoria_correcta":"Va en el resumen"}],"categorias":["Va en el resumen","No va en el resumen"],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Realiza un resumen del texto con las ideas que sí deben incluirse. Después clasifica las oraciones según si van o no van en el resumen.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 13, 'Distingue las tipologías de párrafos por su estructura y función, examinando la articulación entre ideas principales y secundarias para seleccionar las técnicas de procesamiento más adecuadas para su análisis.', 'https://youtu.be/KyugQGU_dH0', null),
  ('df9b1096-abb5-4793-90b0-b68c89290ab6', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', 'Mayúsculas y minúsculas', 'Este texto tiene errores de mayúsculas y minúsculas. Reescríbelo corrigiendo solo eso.', '{"temas":["Mayúsculas al inicio de oración","Nombres propios","Días y materias van en minúscula"],"contexto":"Lee el texto completo antes de corregirlo. Todos los errores son de mayúsculas o minúsculas.","texto_correcto":"La autorregulación del aprendizaje no es un talento con el que se nace, sino una habilidad que se entrena con la práctica. Regina, estudiante de primer semestre, decidió aplicarla en su rutina de estudio para el examen de biología. Antes de empezar, se preguntó qué sabía del tema y qué le faltaba por repasar. Cada domingo organizaba su semana en un calendario y anotaba cuánto tiempo dedicaría a cada materia, incluyendo lunes y jueves, los días con más carga. Si terminaba antes de lo previsto, revisaba si de verdad había comprendido o solo había memorizado. Con el tiempo notó que planear con calma, en vez de estudiar por impulso, la ayudaba a llegar más tranquila a cada evaluación.","texto_incorrecto":"la autorregulación del aprendizaje no es un talento con el que se nace, sino una habilidad que se entrena con la práctica. regina, estudiante de primer semestre, decidió aplicarla en su rutina de estudio para el examen de Biología. antes de empezar, se preguntó qué sabía del tema y qué le faltaba por repasar. cada domingo organizaba su semana en un calendario y anotaba cuánto tiempo dedicaría a cada materia, incluyendo Lunes y Jueves, los días con más carga. si terminaba antes de lo previsto, revisaba si de verdad había comprendido o solo había memorizado. con el tiempo notó que planear con calma, en vez de estudiar por impulso, la ayudaba a llegar más tranquila a cada evaluación.","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Este texto tiene errores de mayúsculas y minúsculas. Reescríbelo corrigiendo solo eso.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 1, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/hawwu5lied8', null),
  ('aaadbd59-5080-4610-91ec-9cf3292de17f', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', '+ Acentuación', 'Este texto tiene errores de mayúsculas y de acentuación (tildes). Reescríbelo corrigiendo ambos.', '{"temas":["Acentuación general","Tilde diacrítica (él/el, qué/que, más/mas)","Mayúsculas"],"contexto":"Además de mayúsculas, este texto tiene errores de acentuación (tildes), incluidos casos como él/el y qué/que, que cambian de significado según lleven tilde o no.","texto_correcto":"Saber si realmente entendiste un tema, y no solo si lo reconoces, es el corazón de la metacognición. Iván se dio cuenta de que podía leer un capítulo completo y sentir que todo tenía sentido, pero al cerrar el libro no sabía explicarlo con sus propias palabras. Por eso empezó a hacerse preguntas antes, durante y después de estudiar: qué sé ya de esto, qué me está costando trabajo y a quién podría enseñárselo. Cuando la respuesta era confusa, volvía atrás en vez de seguir avanzando sin comprender. Él prefería detenerse un momento en vez de fingir que dominaba algo que en realidad no había entendido, porque sabía que esa honestidad consigo mismo era más útil que una lectura rápida.","texto_incorrecto":"saber si realmente entendiste un tema, y no solo si lo reconoces, es el corazon de la metacognicion. ivan se dio cuenta de que podia leer un capitulo completo y sentir que todo tenia sentido, pero al cerrar el libro no sabia explicarlo con sus propias palabras. por eso empezo a hacerse preguntas antes, durante y despues de estudiar: que se ya de esto, que me esta costando trabajo y a quien podria enseñarselo. cuando la respuesta era confusa, volvia atras en vez de seguir avanzando sin comprender. el preferia detenerse un momento en vez de fingir que dominaba algo que en realidad no habia entendido, porque sabia que esa honestidad consigo mismo era mas util que una lectura rapida.","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Este texto tiene errores de mayúsculas y de acentuación (tildes). Reescríbelo corrigiendo ambos.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 2, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/BuY05JMq88o', null),
  ('da75160a-eaa3-447b-9e73-a224beb5f4ae', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', 'Uso de b y v', 'Reescribe el texto completo. Corrige las mayúsculas y las letras b/v.', '{"temas":["Mayúsculas","B/V"],"contexto":"Este texto tiene errores de mayúsculas y de uso de b y v. Corrige ambos aspectos.","texto_correcto":"Al comenzar la semana, Valeria revisa su horario y escribe en su libreta las actividades que debe resolver. Después observa sus avances, busca una breve explicación cuando se equivoca y vuelve a intentar el ejercicio. Antes de cerrar la sesión, comparte con su equipo lo que aprendió y guarda una evidencia de su trabajo.","texto_incorrecto":"al comenzar la semana, Baleria revisa su horario y escribe en su libreta las actividades que debe resolver. Después observa sus abances, busca una breve explicación cuando se equivoca y buelve a intentar el ejercicio. Antes de cerrar la sesión, comparte con su equipo lo que aprendió y guarda una ebidencia de su trabajo."}'::jsonb, 3, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/H4r72vZkHAc', null),
  ('28648aa1-ae31-4a84-878c-aa2a9ade09d8', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', 'Uso de g y j', 'Reescribe el texto completo. Corrige las mayúsculas, b/v y g/j.', '{"temas":["Mayúsculas","B/V","G/J"],"contexto":"Este texto reúne errores de mayúsculas, b/v y g/j. Corrige las tres grafías.","texto_correcto":"Jorge organizó un viaje para que su grupo conociera el museo. Primero eligió una ruta breve, después dirigió al equipo y revisó que todos tuvieran claro el objetivo. Al final, cada persona escribió qué aprendió y cómo volvería a usar esa estrategia en otro trabajo.","texto_incorrecto":"jorge organizó un biaje para que su grupo conociera el museo. Primero elijió una ruta breve, después dirijió al equipo y revisó que todos tubieran claro el objetivo. Al final, cada persona escribió qué aprendió y cómo bolbería a usar esa estrategia en otro trabajo."}'::jsonb, 4, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/FUFu6X1lguA', null),
  ('6e685bbc-fb08-4ea4-80a7-aad23082e362', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', 'Uso de s, c y z', 'Reescribe el texto completo. Corrige las mayúsculas, b/v, g/j y s/c/z.', '{"temas":["Mayúsculas","B/V","G/J","S/C/Z"],"contexto":"Este texto reúne errores de mayúsculas, b/v, g/j y s/c/z. Corrige las cuatro grafías.","texto_correcto":"La decisión de cambiar de estrategia fue precisa y útil. Luisa organizó sus notas, visualizó el problema y avanzó paso a paso. Después revisó cada ejercicio, conoció sus errores y escribió una conclusión para explicar qué debía mejorar.","texto_incorrecto":"la desición de cambiar de estrategia fue presisa y útil. luisa organisó sus notas, bisualisó el problema y abansó paso a paso. Después revisó cada ejersicio, conoseió sus errores y escrivió una conclusión para explicar qué debía mejorar."}'::jsonb, 5, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/RZ-8i2eTMrA', null),
  ('2f3ac162-d9e6-45f0-84fa-63230f3bd5c5', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', 'Uso de h', 'Reescribe el texto completo. Corrige las mayúsculas, b/v, g/j, s/c/z y h.', '{"temas":["Mayúsculas","B/V","G/J","S/C/Z","H"],"contexto":"Este texto reúne errores de mayúsculas y de las grafías b/v, g/j, s/c/z y h. Corrige todo lo que ya practicaste.","texto_correcto":"Hoy el grupo habló sobre el hábito de revisar antes de entregar. El profesor explicó hacia dónde mirar cuando una palabra causa duda y pidió hacer una lista de ejemplos. Javier escribió sus respuestas, organizó las ideas y decidió volver a leer el texto para encontrar cada error.","texto_incorrecto":"oy el grupo abló sobre el ábito de revisar antes de entregar. el profesor explicó asia dónde mirar cuando una palabra causa duda y pidió acer una lista de ejemplos. javier escrivió sus respuestas, organisó las ideas y desidió bolber a leer el texto para encontrar cada error."}'::jsonb, 6, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/B3tsp17XQFM', null),
  ('02e9a559-169b-4c3d-a923-a7f6b3c03110', 'f018d57c-10e0-43ed-9112-d003596e02d9', '9320ca3b-9c19-4b49-a720-26551b3ae444', 'Repaso integrador de ortografía', 'El texto más completo: mezcla mayúsculas, tildes y letras que se confunden. Reescríbelo corrigiendo todos los errores que encuentres.', '{"temas":["Mayúsculas","Acentuación","Tildes diacríticas","Letras que se confunden"],"contexto":"Lee todo el texto antes de corregirlo. Junta mayúsculas, tildes (incluidas las diacríticas) y letras que se confunden en un mismo texto.","texto_correcto":"Cuando terminó el semestre, Fernanda se dio cuenta de que ya no dependía tanto de que alguien más le dijera qué estudiar y cómo hacerlo. Al principio necesitaba que su profesor le explicara paso a paso cada estrategia, pero poco a poco empezó a decidir por sí misma cuánto tiempo dedicarle a cada materia y cuándo pedir ayuda. Antes de cada examen se preguntaba qué tanto dominaba el tema, y si la respuesta la dejaba insegura, volvía a explicar el contenido en voz alta hasta sentirse segura. Cuando se equivocaba, revisaba el error con calma en vez de evitarlo, y ajustaba su manera de organizar el siguiente repaso. Esa autonomía, más que cualquier técnica en particular, fue lo que más la ayudó a sostener su aprendizaje a lo largo del semestre.","texto_incorrecto":"cuando termino el semestre, fernanda se dio cuenta de que ya no dependia tanto de que alguien mas le dijera que estudiar y como acerlo. al principio necesitaba que su profesor le explicara paso a paso cada estrategia, pero poco a poco empezo a decidir por si misma cuanto tiempo dedicarle a cada materia y cuando pedir ayuda. antes de cada examen se preguntaba que tanto dominaba el tema, y si la respuesta la dejaba insegura, volvia a explicar el contenido en voz alta hasta sentirse segura. cuando se equibocaba, rebisaba el error con calma en ves de evitarlo, y ajustaba su manera de orjanizar el siguiente repaso. esa autonomia, mas que cualquier tecnica en particular, fue lo que mas la ayudo a sostener su aprendizage a lo largo del semestre.","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"El texto más completo: mezcla mayúsculas, tildes y letras que se confunden. Reescríbelo corrigiendo todos los errores que encuentres.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 7, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', null, null),
  ('089e0d15-acec-4886-b258-8deed6169154', 'f018d57c-10e0-43ed-9112-d003596e02d9', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Vicios de la redacción', 'Lee cada oración e identifica el vicio de redacción que presenta. Si la oración es clara y correcta, elige "Uso correcto".', '{"contexto":"Los vicios de redacción afectan la claridad, la precisión o la corrección de un mensaje. Reconoce el problema antes de corregirlo.","elementos":[{"texto":"La estudiante revisó su borrador antes de entregarlo.","categoria_correcta":"Uso correcto"},{"texto":"Ayer andé al mercado para comprar los materiales.","categoria_correcta":"Barbarismo"},{"texto":"Hubieron muchos errores en el primer borrador.","categoria_correcta":"Solecismo"},{"texto":"Lo vi con mis propios ojos.","categoria_correcta":"Pleonasmo"},{"texto":"Parece que aparece una respuesta distinta en cada intento.","categoria_correcta":"Cacofonía"},{"texto":"El director habló con el estudiante de su proyecto y luego él se fue.","categoria_correcta":"Anfibología"},{"texto":"Me alegro que hayas revisado tus respuestas.","categoria_correcta":"Queísmo"},{"texto":"Pienso de que la actividad quedó clara.","categoria_correcta":"Dequeísmo"}],"categorias":["Uso correcto","Barbarismo","Solecismo","Pleonasmo","Cacofonía","Anfibología","Queísmo","Dequeísmo"]}'::jsonb, 8, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/Ud8qpqlQ1PY', null),
  ('5a422310-a464-4bc6-bff3-db1e0f73bbd0', 'f018d57c-10e0-43ed-9112-d003596e02d9', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Modelo expositivo general', 'Observa el video. Lee el texto y reconoce la estructura general de un texto expositivo. Justifica tu elección con una idea clave.', '{"intro":"Un texto expositivo general presenta un tema, desarrolla información y cierra recuperando la idea central.","rondas":[{"contexto":"La energía solar es una fuente renovable que aprovecha la radiación del sol para producir electricidad. Los paneles solares convierten esa radiación en energía eléctrica y, cuando se integran con un consumo responsable, pueden disminuir el uso de combustibles fósiles. En conclusión, se trata de una alternativa que combina el aprovechamiento tecnológico con la reducción del impacto ambiental.","opciones":["Introducción, desarrollo y conclusión","Causa-Efecto","Cronológico","Confrontación"],"pregunta":"¿Qué estructura general sigue este texto?","ideas_clave":["presenta el tema","explica su funcionamiento y sus beneficios","cierra con una valoración final"],"respuesta_correcta":"Introducción, desarrollo y conclusión"}],"presentacion":"todas_juntas"}'::jsonb, 9, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/IsjQnbKel6s', null),
  ('9ff59e7e-c3f1-439d-ad91-e3846dde5820', 'f018d57c-10e0-43ed-9112-d003596e02d9', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Modelo causa-efecto', 'Observa el video. Lee el texto, identifica la causa y el efecto, y justifica tu elección con una idea clave.', '{"intro":"El modelo causa-efecto explica por qué ocurre un hecho y qué consecuencia produce.","rondas":[{"contexto":"Dormir poco puede afectar el aprendizaje. Cuando una persona descansa menos de lo necesario, mantiene la atención durante menos tiempo y le cuesta recordar lo que estudió. Por eso, organizar un horario de sueño favorece la concentración durante la jornada escolar.","opciones":["Causa-Efecto","Cronológico","Tesis-Antítesis-Síntesis","Confrontación"],"pregunta":"¿Qué modelo expositivo sigue este texto?","ideas_clave":["dormir poco","afecta el aprendizaje","por eso"],"respuesta_correcta":"Causa-Efecto"}],"presentacion":"todas_juntas"}'::jsonb, 10, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/yppNsvTosis', null),
  ('7281474d-d06d-4628-967b-da7a87f4d53a', 'f018d57c-10e0-43ed-9112-d003596e02d9', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Modelo de tesis', 'Observa el video. Lee el texto, identifica la tesis, la antítesis y la síntesis, y justifica tu elección con una idea clave.', '{"intro":"El modelo de tesis presenta una tesis o postura, considera una antítesis o postura contraria y llega a una síntesis que integra ambos puntos de vista.","rondas":[{"contexto":"Incorporar el celular con reglas claras puede apoyar el aprendizaje, porque permite consultar fuentes y participar en actividades interactivas. Sin embargo, otras personas consideran que debe prohibirse durante la clase, ya que las notificaciones y el uso de redes sociales pueden distraer y dificultar la atención. En síntesis, el celular puede utilizarse de manera provechosa si el docente establece momentos, propósitos y reglas claras.","opciones":["Causa-Efecto","Cronológico","Tesis-Antítesis-Síntesis","Confrontación"],"pregunta":"¿Qué modelo expositivo sigue este texto?","ideas_clave":["tesis o postura inicial","antítesis o postura contraria","síntesis que integra ambas posturas"],"respuesta_correcta":"Tesis-Antítesis-Síntesis"}],"presentacion":"todas_juntas"}'::jsonb, 11, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/Rwn1A0425eg', null),
  ('673eae74-9c7f-4ecb-ab34-6d0a00c80dc2', 'f018d57c-10e0-43ed-9112-d003596e02d9', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Modelo de confrontación', 'Observa el video. Lee el texto, identifica las dos posiciones que se comparan y justifica tu elección.', '{"intro":"El modelo de confrontación presenta dos opciones o posiciones y contrasta sus características, ventajas o limitaciones.","rondas":[{"contexto":"Trabajar de manera individual permite avanzar al propio ritmo y tomar decisiones sin esperar a otras personas. En cambio, trabajar en equipo facilita compartir ideas y distribuir las tareas, aunque exige ponerse de acuerdo. Las dos formas pueden ser útiles según el propósito y el tiempo disponible.","opciones":["Causa-Efecto","Cronológico","Tesis-Antítesis-Síntesis","Confrontación"],"pregunta":"¿Qué modelo expositivo sigue este texto?","ideas_clave":["trabajo individual","en cambio","trabajo en equipo"],"respuesta_correcta":"Confrontación"}],"presentacion":"todas_juntas"}'::jsonb, 12, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/bacAPUP_90Q', null),
  ('20267aa3-8d20-44bc-9da4-08056fa390fc', 'f018d57c-10e0-43ed-9112-d003596e02d9', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Modelo cronológico', 'Observa el video. Lee el texto, reconoce el orden temporal de las acciones y justifica tu elección con una idea clave.', '{"intro":"El modelo cronológico organiza la información según el orden en que suceden los hechos o los pasos de un proceso.","rondas":[{"contexto":"Primero, el equipo eligió el tema de su exposición. Después, buscó información en dos fuentes y tomó notas. Luego organizó las ideas en un esquema y preparó las imágenes. Finalmente, ensayó la presentación y ajustó el tiempo de cada integrante.","opciones":["Causa-Efecto","Cronológico","Tesis-Antítesis-Síntesis","Confrontación"],"pregunta":"¿Qué modelo expositivo sigue este texto?","ideas_clave":["primero","después","finalmente"],"respuesta_correcta":"Cronológico"}],"presentacion":"todas_juntas"}'::jsonb, 13, 'Distingue diversas estructuras de oraciones, contrastando el uso de los diferentes tipos de léxico, gramática, y propiedades textuales para determinar su cohesión y coherencia.', 'https://youtu.be/hhBapygAB7M', null),
  ('1db9287e-31db-45ff-9351-5bb8a127896b', '9f8dc167-716f-40f6-ade9-815849af66f8', 'b98b891f-f800-4a81-988a-67b26bf1b2a7', 'Cualidades internas y externas de la exposición oral', 'Vas a ver dos videos de exposición oral. En el Video A, marca qué cualidades sí identificas. En el Video B, marca qué cualidades le hacen falta.', '{"intro":"Estas son algunas de las cualidades internas y externas de la exposición oral que ya conoces. Obsérvalas en cada video.","video_mal":{"url":null,"ausentes":["Volumen","Dicción","Ritmo","Tono y modulación","Movimientos corporales y gesticulación","Organización de las ideas","Conocimiento del público","Autodominio"]},"cualidades":["Volumen","Dicción","Ritmo","Tono y modulación","Movimientos corporales y gesticulación","Organización de las ideas","Conocimiento del público","Autodominio"],"video_bien":{"url":null,"presentes":["Volumen","Dicción","Ritmo","Tono y modulación","Movimientos corporales y gesticulación","Organización de las ideas","Conocimiento del público","Autodominio"]},"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Vas a ver dos videos de exposición oral. En el Video A, marca qué cualidades sí identificas. En el Video B, marca qué cualidades le hacen falta.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 1, 'Distingue las cualidades internas y externas, examinando cómo la articulación de la voz y los movimientos corporales determinan el impacto de la presentación en el público.', 'https://youtu.be/b1avNGeJZlA', null),
  ('6911bd9b-4a62-4499-9e05-a026d5064d5e', '9f8dc167-716f-40f6-ade9-815849af66f8', '4b36a5f1-6efc-42d0-af47-ecf3d26c6ea3', 'Elementos no verbales de la exposición', 'Clasifica cada elemento no verbal según el tipo de comunicación no verbal al que pertenece.', '{"elementos":[{"texto":"Mantener contacto visual con el público","categoria_correcta":"Kinésica (movimiento corporal)"},{"texto":"Gesticular con las manos para enfatizar una idea","categoria_correcta":"Kinésica (movimiento corporal)"},{"texto":"Pararse cerca o lejos del público según la formalidad del evento","categoria_correcta":"Proxémica (uso del espacio)"},{"texto":"Moverse por el escenario en vez de quedarse estático en un solo punto","categoria_correcta":"Proxémica (uso del espacio)"},{"texto":"El tono de voz que sube o baja para dar énfasis","categoria_correcta":"Paralingüística (voz sin las palabras)"},{"texto":"Las pausas y los silencios estratégicos al hablar","categoria_correcta":"Paralingüística (voz sin las palabras)"}],"categorias":["Kinésica (movimiento corporal)","Proxémica (uso del espacio)","Paralingüística (voz sin las palabras)"],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Clasifica cada elemento no verbal según el tipo de comunicación no verbal al que pertenece.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 2, 'Distingue las cualidades internas y externas, examinando cómo la articulación de la voz y los movimientos corporales determinan el impacto de la presentación en el público.', 'https://youtu.be/em_-_65ZfSk', null),
  ('6cc0ad0e-1e4b-427f-88da-beb844f9a4dd', '9f8dc167-716f-40f6-ade9-815849af66f8', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Técnica ante un escenario: un solo compañero', 'Lee cada situación y elige, pensando en tu compañero, qué técnica de exposición oral conviene usar.', '{"rondas":[{"contexto":"Tu compañero faltó a la clase donde se explicó cómo funciona el ciclo del agua y te pide que se lo expliques tú, con calma y desde cero, antes del examen de mañana.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica te conviene usar para explicarle el tema con claridad?","ideas_clave":["explicar","claro","paso a paso"],"respuesta_correcta":"Exposición"},{"contexto":"Quieres convencer a tu compañero de que se una contigo a un proyecto extracurricular de lectura. Tienes solo dos minutos para lograr que diga que sí.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica es más adecuada para persuadirlo de unirse al proyecto?","ideas_clave":["persuadir","convencer","emoción"],"respuesta_correcta":"Discurso"},{"contexto":"Tu compañero te pide que le expliques, paso a paso y sin apurarte, cómo se conjugan los verbos irregulares porque no entendió la clase.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica te ayuda a explicarle el tema con claridad?","ideas_clave":["explicar","informar","organizar"],"respuesta_correcta":"Exposición"},{"contexto":"Tu compañero está desmotivado y a punto de dejar el proyecto de ciencias a medias. Quieres animarlo a que no se rinda y lo termine.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica te ayuda mejor a motivarlo con tus palabras?","ideas_clave":["motivar","emoción","convencer"],"respuesta_correcta":"Discurso"}],"presentacion":"todas_juntas","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee cada situación y elige, pensando en tu compañero, qué técnica de exposición oral conviene usar.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 3, 'Selecciona la técnica y modalidad expositivas valorando la estrategia de comunicación para emitir mensajes orales, con base al contexto e intención comunicativa.', 'https://youtu.be/a6wGMRdRD44', null),
  ('a006bfe6-4965-417a-a450-c387bbeb46ef', '9f8dc167-716f-40f6-ade9-815849af66f8', 'd453abcd-d7ab-4355-af1f-70f76c57fb54', 'Técnica ante un escenario: todo el grupo', 'Lee cada situación grupal y elige qué técnica de exposición oral conviene usar.', '{"rondas":[{"contexto":"En tu salón hay opiniones divididas sobre si debería permitirse usar el celular durante los exámenes. La maestra pide que dos posturas se enfrenten con argumentos frente al grupo.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica corresponde a esta situación?","ideas_clave":["posturas","argumentos","contraargumento"],"respuesta_correcta":"Debate"},{"contexto":"Cuatro estudiantes con opiniones distintas sobre el uso de la inteligencia artificial en la escuela comparten su punto de vista frente al grupo, moderados por un quinto compañero que da la palabra por turnos.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica corresponde a esta situación?","ideas_clave":["moderador","turnos","varias posturas"],"respuesta_correcta":"Mesa redonda"},{"contexto":"La mitad del grupo piensa que los uniformes deberían ser obligatorios y la otra mitad no. La maestra pide que ambos lados defiendan su postura con argumentos frente a todos.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica corresponde a esta situación?","ideas_clave":["posturas","argumentos","contraargumento"],"respuesta_correcta":"Debate"},{"contexto":"Cinco estudiantes con distintas opiniones sobre cómo debería ser la ceremonia de graduación exponen su punto de vista frente al grupo, mientras un compañero modera y da la palabra por turnos.","opciones":["Exposición","Discurso","Debate","Mesa redonda"],"pregunta":"¿Qué técnica corresponde a esta situación?","ideas_clave":["moderador","turnos","varias posturas"],"respuesta_correcta":"Mesa redonda"}],"presentacion":"todas_juntas","instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Lee cada situación grupal y elige qué técnica de exposición oral conviene usar.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 4, 'Selecciona la técnica y modalidad expositivas valorando la estrategia de comunicación para emitir mensajes orales, con base al contexto e intención comunicativa.', 'https://youtu.be/a6wGMRdRD44', null),
  ('9553e7d8-ebd5-495e-83d7-13fcadac1981', '9f8dc167-716f-40f6-ade9-815849af66f8', '9022a3dc-77f3-48ca-b493-a63f4aaedcbf', 'Exposición individual vs. en equipo', 'Arrastra (o toca) la respuesta correcta del banco hasta la celda que le corresponde. Compara ambas formas de exponer.', '{"conceptos":["Exposición individual","Exposición en equipo"],"criterios":["Preparación del contenido","Qué pasa si algo sale mal","Nivel de dominio que debes tener del tema completo","Distribución del trabajo","Tiempo de organización necesario"],"celda_correcta":[["Tú decides y armas todo el material, sin necesidad de ponerte de acuerdo con nadie.","Se reparte el material por temas, y luego hay que unir las partes para que se vea como un solo trabajo."],["Si te equivocas o te bloqueas, no hay nadie que pueda tomar tu lugar en ese momento.","Un compañero puede intervenir o apoyar si alguien se traba o se le olvida algo."],["Necesitas conocer todo el tema a fondo, porque tú expones cada parte.","Debes dominar tu parte y comprender la idea general del resto para mantener la coherencia y responder preguntas."],["Todo el trabajo de investigar, preparar y exponer recae en una sola persona.","El trabajo se divide entre varios, pero requiere coordinarse para que las partes conecten bien."],["Puedes empezar a preparar en cuanto quieras, sin esperar a nadie más.","Hay que encontrar horarios en común para ensayar juntos antes de exponer."]],"banco_respuestas":["Tú decides y armas todo el material, sin necesidad de ponerte de acuerdo con nadie.","Se reparte el material por temas, y luego hay que unir las partes para que se vea como un solo trabajo.","Si te equivocas o te bloqueas, no hay nadie que pueda tomar tu lugar en ese momento.","Un compañero puede intervenir o apoyar si alguien se traba o se le olvida algo.","Necesitas conocer todo el tema a fondo, porque tú expones cada parte.","Basta con dominar bien tu parte; del resto solo necesitas una idea general.","Todo el trabajo de investigar, preparar y exponer recae en una sola persona.","El trabajo se divide entre varios, pero requiere coordinarse para que las partes conecten bien.","Puedes empezar a preparar en cuanto quieras, sin esperar a nadie más.","Hay que encontrar horarios en común para ensayar juntos antes de exponer.","Siempre es mejor exponer en equipo, sin importar el tema.","El profesor asigna al azar quién expone individualmente.","No importa cómo te prepares, el resultado es siempre el mismo.","Solo se puede exponer en equipo si son exactamente tres personas."],"instrucciones_momentos":{"video":"Observa el video con atención. Identifica una idea, ejemplo o estrategia que te ayude a resolver la actividad.","actividad":"Arrastra (o toca) la respuesta correcta del banco hasta la celda que le corresponde. Compara ambas formas de exponer.","presentacion":"Lee el propósito de la actividad y piensa qué esperas comprender o lograr antes de continuar."}}'::jsonb, 5, 'Selecciona la técnica y modalidad expositivas valorando la estrategia de comunicación para emitir mensajes orales, con base al contexto e intención comunicativa.', 'https://youtu.be/TnUIz5CfVMg', null)
